"""This library contain all Attenuator related keywords. Keywords support JFW attenuator


    = Configuration Needed =
    === testline_config ===
    |
    | _*"attenuator"*_:
    | {
    | *"jfw_atten_name1"*:{                 User defined name for the attenuator device.
    |   *"tool"*:"jfw",                     The make of the device
    |   *"ip"*:"10.53.186.45",              The Telnet IP of the device
    |   *"user"*:"",                        Telnet username
    |   *"password"*:"",                    Telnet password
    |   *"telnet_port"*:"3001",             Telnet port
    |   *"prompt"*:"",                      Telnet prompt.
    |   *"source_ports"*:[10],              List of attenuator ports from where handover should
    |                                       start
    |   *"target_ports"*:[11]               List of attenuator ports to where handover should
    |                                       happen
    | }
    |}

    === testcase_variables ===
    | *"attenuator_profiles"* : {
    |	_*"profile_name1"*_: {              User defined profile name
    |       *"initial_atten"*: "10",        Initial attenuation value for source ports
    |    	*"max_atten"*: "60",            Max attenuation for source_ports in attenuation
    |                                       increasing cycle.
    |                                       Initial attenuation for source_ports in attenuation
    |                                       decreasing cycle.
    |                                       Half-of this max atten is the initial atten for target
    |                                       ports.
    |    	*"cycles"*: "10",               Number of cycles. Increasing to max attempt and
    |                                       decreasing to initial attempt is one cycle
    |    	*"delay_per_direction"*: "10",  Delay in seconds after completing changing attenuation
    |                                       in one direction(half-cycle).
    |    	*"atten_change_step"*: "1",     The level of attenuation change for each step.
    |    	*"atten_change_delay"*: "1"     Delay in seconds after each attenuation change step.
    | }
    |}

    = Example =

    | ***** Test Cases *****
    | Set Attenution
    |     Attenuator Setup  device=jfw_atten    alias=jfwalias
    |     Attenuator Configure  operation=set_attenuation    ports=${att_ports}  atten_val=10
    |        alias=jfwalias
    |     Attenuator Teardown   alias=jfwalias
    |
    | Perform Handover
    |     Attenuator Setup  device=jfw_atten    alias=jfwalias
    |     Attenuator Configure  operation=perform_hand_over   profile=atten_prof1   alias=jfwalias
    |     Attenuator Teardown   alias=jfwalias
"""

from taf.ul.trs_e2e_fw.lib.attenuator.attenuator_manager import AttenuatorManager


def attenuator_setup(device='device_1', alias='default'):
    """This keyword is used to setup attenuator device. Currently JFW is supported

       | *Arguments* | *Comments* | *default*|
       | device | Device name according to Testline config | device_1 |
       | alias | Context Manager | default |

        *Examples:*

        *Setup a device for attenuation with default arguments*
        | Attenuator Setup | device=jfw_atten | alias=jfwalias |

        *Configurations Needed :*
        `testline_config` sections:
        "attenuator"
    """
    return AttenuatorManager().attenuator_setup(device=device, alias=alias)


def attenuator_configure(operation, alias='default', **kwargs):
    """
        Configures attenuator based on the given operation
                | *Arguments* | *Comments* | *default*|
                | operation | set_attenuation or perform_hand_over | |
                | alias | Context Manager | default |

        Kwarg arguments needed for operation *set_attenuation* which sets given attenuation for
        all given ports
                | *Arguments* | *Comments* | *default*|
                | ports | List of ports to be set with an attenuation level | |
                | atten_val | Attenuation level | |

        Kwarg arguments needed for *operation* *perform_hand_over* .
                | *Arguments* | *Comments* | *default*|
                | profile | Name of the profile according to testcase config |  |

        *Configurations Needed :*

                `testcase_config` sections:
                "attenuator_profiles"

        *Examples:*

            *Set attenuation for given ports to 10*
            | ${att_ports}= | Get Config Variable | ${att_ports_path} |
            | Attenuator Configure | operation=set_attenuation | ports=${att_ports} | atten_val=10
                | alias=jfwalias |

            *Peform Handover for given profile*
            | Attenuator Configure | operation=perform_hand_over | profile=atten_prof1 |
                alias=jfwalias |

    """
    return AttenuatorManager().attenuator_configure(operation=operation, alias=alias, **kwargs)


def attenuator_teardown(alias='default'):
    """
        Closes connection for the device under the given alias and removes the context.
            | *Arguments* | *Comments* | *default*|
            | alias | Context Manager | default |
    """
    return AttenuatorManager().attenuator_teardown(alias=alias)
